import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Lua Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"en/development/lua/index.md","filePath":"en/development/lua/index.md","lastUpdated":1791683719000}`),a={name:`en/development/lua/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="lua-scripts" tabindex="-1">Lua Scripts <a class="header-anchor" href="#lua-scripts" aria-label="Permalink to “Lua Scripts”">​</a></h1><p>Lua scripts provide a flexible way to extend Xray, implement custom functionality, and interact with the core.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting Started”">​</a></h2><p>Start with <a href="./environment.html">Runtime Environment and Script Loading</a> to learn about Lua support, module loading, and how script files are located.</p><h2 id="writing-guides" tabindex="-1">Writing Guides <a class="header-anchor" href="#writing-guides" aria-label="Permalink to “Writing Guides”">​</a></h2><p>Choose a guide for the functionality you need, start with the minimal example, and build your own script step by step:</p><table tabindex="0"><thead><tr><th>Guide</th><th>Purpose</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./guide/routing.html">Routing Scripts</a></td><td>Customize routing rules</td><td>Outbound selection, load balancing, and IP-based routing after explicit resolution</td></tr><tr><td><a href="./guide/dns.html">DNS Scripts</a></td><td>Customize DNS queries</td><td>Upstream selection, query fallback, and result filtering</td></tr></tbody></table><p>The current routing and DNS scripts both use pooled instances. When writing scripts, read about the <a href="./guide/lifecycle.html#pooled-lifecycle">pooled lifecycle</a> to understand top-level initialization and state retention.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to “Reference”">​</a></h2><h3 id="hook" tabindex="-1">Hook <a class="header-anchor" href="#hook" aria-label="Permalink to “Hook”">​</a></h3><p>A Hook is a Lua function that the core calls at a specific point. The script entry point determines the available Hooks and their calling conventions; one entry point can have multiple Hooks. Refer to the documentation for each entry point to find out which Hooks you need to implement.</p><p>The currently supported entry points and Hooks are listed below. See each Hook&#39;s reference page for parameters, return values, and failure behavior:</p><table tabindex="0"><thead><tr><th>Script entry point</th><th>Hook</th></tr></thead><tbody><tr><td><code>routing.script</code></td><td><a href="./reference/hook-routing.html">HandleRoute</a></td></tr><tr><td><code>dns.script</code></td><td><a href="./reference/hook-dns.html">HandleDNSQuery</a></td></tr></tbody></table><h3 id="data-types" tabindex="-1">Data Types <a class="header-anchor" href="#data-types" aria-label="Permalink to “Data Types”">​</a></h3><p>In addition to Lua&#39;s built-in types, Xray Lua uses types such as <code>net.IP</code>, Go slices, and <code>error</code>. See <a href="./reference/data-types.html">Data Types</a> for their representation and use in Lua.</p><h3 id="module-api" tabindex="-1">Module API <a class="header-anchor" href="#module-api" aria-label="Permalink to “Module API”">​</a></h3><p>Browse the module APIs by functionality:</p><table tabindex="0"><thead><tr><th>Module</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="./reference/module-router.html">xray.router</a></td><td>Policy routing</td></tr><tr><td><a href="./reference/module-dns.html">xray.dns</a></td><td>Domain resolution</td></tr><tr><td><a href="./reference/module-geodata.html">xray.geodata</a></td><td>Domain and IP matching and filtering</td></tr><tr><td><a href="./reference/module-log.html">xray.log</a></td><td>Log output</td></tr></tbody></table>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};